    static IslandStory[] ChoirIsles() => [
        Isle("Choir Deep",6,"Cot Eleven","Reva Rusk, night sister",
            "Reva can tell which cot needs her by the vibration in a copper rail. The survey barge cut that rail to make a convenient tuning fork. Three nights have passed without a single call from the outer ward.",
            "A copper button that hums against the table",
            Crossing("cot-fork",D.Salvage,"The Borrowed Note",
                "The surveyor dropped his fork between two singing reefs. Struck on the port tine it sounds like a request for water. On the starboard tine it asks somebody to turn a pillow.",
                "Recover the copper ward rail from the survey moorings.","Tuning Ray",
                "Reva lays the fork against her wrist. Cot eleven has been calling steadily throughout the search.",7,J.Sound,J.Salvage,J.Unload),
            Landfall("cot-thread","A Hand on the Rail",
                "Patient Ivo has been tapping with a thimble. He can feel the long run of copper shift under the deck but cannot get out of bed to show where its last joint parted.",
                "Copper Louse","The new rail carries Ivo's thimble clear across the ward. His first message asks if anybody else would care for a turn at sending.",6,
                At(A.Haul,S.Crane,"Copper rail","Haul the heavy rail back to cot height"),
                At(A.Seat,S.West,"Outer joint","Seat the outer joint beneath Ivo’s hand"),
                At(A.Brace,S.East,"Deck coupling","Brace the coupling while Reva listens")),
            Crossing("cot-beds",D.Convoy,"Four Long Taps",
                "Four long taps mean move the ward. The boats rehearsed the maneuver before the rail was cut. The youngest volunteer has managed never to learn which end of the practice pillow goes first.",
                "Guide the relief beds between the reefs under Reva’s hand signal.","Mattress Cusk",
                "Every bed reaches shelter with its pillow. One extra pillow arrives alone and is admitted for observation.",7,J.Tow,J.Guide,J.Relieve),
            Landfall("cot-door","The Outside Bell",
                "The outer ward has become very good at calling in. Ivo asks how somebody outside the hospital is supposed to call for a bed. Reva lends him her thimble.",
                "Casement Snail","A fisher taps the new copper plate to ask whether visiting hours have started. Ivo taps back that they have now.",6,
                At(A.Cut,S.Fallen,"Window packing","Open a passage through the old window packing"),
                At(A.Turn,S.East,"Bronze lead","Turn the lead toward the landing"),
                At(A.Seat,S.Stairs,"Visitor plate","Set the caller’s plate at a child’s height"))),
        Isle("Choir Deep",6,"Underhum Bridge","Ume Fallow, bridge tender",
            "There has never been a road to either end of Underhum Bridge. Its purpose was to carry a song across a gap in the reef. Ume's father forgot the middle verse, so both halves of the bridge have spent eighteen years singing at once.",
            "A bridge ticket printed on a mussel shell",
            Crossing("hum-middle",D.Sounding,"The Missing Measure",
                "There is a silent patch between the two songs. Ume wants the boat to enter it from three directions so she can tell a missing note from two notes that cancel each other.",
                "Chart the quiet patch beneath the middle span.","Restbeat Skate",
                "In the silence Vara hears an old ferry engine turning. Ume's father used to time the middle verse to its paddles.",7,J.Sound,J.Track,J.Sound),
            Crossing("hum-engine",D.Hunt,"A Ferry You Can Hear",
                "The paddle sound moves at night. A reef dolphin learned it from the original ferry and still swims the route with six smaller dolphins in its wake.",
                "Find the paddle singer without scattering its school.","Paddleporpoise",
                "Ume sings the first verse over the side. Seven dolphins answer with the middle one and demand seven fares in fish.",7,J.Track,J.Bait,J.DriveOff),
            Landfall("hum-walk","A Bridge for Music",
                "The middle span sags out of tune. Ume can set its tension if one end holds the song while the other turns the screw. Her father offers to hold the screw. He remembers what happened last time.",
                "Tension Whelk","Song passes cleanly through the span. Ume’s father adds the last verse in a voice nobody on the island knew he still had.",7,
                At(A.Brace,S.West,"Singing span","Brace the low span at the dolphin’s pitch"),
                At(A.Turn,S.East,"Bridge screw","Tighten the bridge screw to the middle note"),
                At(A.Guide,S.Stairs,"First bridge singer","Escort Ume’s father across the tuned boards")),
            Crossing("hum-fare",D.Blockade,"Tickets for Dolphins",
                "The registry hears a ferry running and stretches a toll wire across the dolphin route. Ume has printed seven tickets. The clerk says they must be signed.",
                "Clear the toll wire and carry the song to the hospital fleet.","Ticket Punch",
                "Seven fish-shaped holes appear in seven tickets. The clerk accepts them. His lunch has been signed in the same way.",7,J.Cut,J.DriveOff,J.Relay)),
        Isle("Choir Deep",6,"Hushbox Head","Tern Vale, voice archivist",
            "Tern maintains a room of speaking shells left by people going into surgery. Most owners come back for their voices. One shell has spoken every evening for forty years and nobody has ever asked for it.",
            "A shell lined in purple recording wax",
            Landfall("hush-shelf","Evening Deposit",
                "The unclaimed shell has worn a hollow under its shelf. Tern is afraid the next message will bring half the archive down on it.",
                "Sill Hermit","The shell says three words: put it there. Nell recognizes the accent of an island that disappeared from the chart before she was born.",6,
